/**
 * The API reference of a product's `/docs` page, from its `openapi.json` (generated by `ss app assets` from the routes
 * and `schemas/api.json`): every operation with its auth, feature, parameters, request fields and answer fields, then
 * the shared objects. Plain HTML; every value is escaped. A string builder only: the description is the product's own
 * build-time JSON.
 * @module
 */
import { isObject } from '@ss/contracts/util';
import { escapeHtml as escape } from '@ss/contracts/text';

/** @typedef {Record<string, any>} Node */

/** The shared schema a `$ref` names, or null. @param {unknown} ref */
const refName = (ref) => (typeof ref === 'string' ? (/^#\/components\/schemas\/(.+)$/.exec(ref)?.[1] ?? null) : null);

/**
 * The anchor of an operation on the page (`#op-get-v1-payments-id`).
 * @param {string} method
 * @param {string} path
 */
export const apiAnchor = (method, path) =>
	`op-${`${method} ${path}`
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-|-$/g, '')}`;

/** @param {string} name */
const schemaAnchor = (name) => `schema-${name.replace(/[^A-Za-z0-9_-]/g, '-')}`;

/**
 * A schema's type as HTML (`string | null`, `array of <a>Payment</a>`, `"paid" | "failed"` …).
 * @param {unknown} schema
 * @returns {string}
 */
const typeOf = (schema) => {
	if (!isObject(schema)) return 'any';
	const name = refName(schema.$ref);
	if (name !== null) return `<a href="#${escape(schemaAnchor(name))}">${escape(name)}</a>`;
	if (Array.isArray(schema.enum)) return schema.enum.map((value) => escape(JSON.stringify(value))).join(' | ');
	if (Object.hasOwn(schema, 'const')) return escape(JSON.stringify(schema.const));
	const branches = Array.isArray(schema.oneOf) ? schema.oneOf : Array.isArray(schema.anyOf) ? schema.anyOf : null;
	if (branches) return branches.map(typeOf).join(' or ');
	if (schema.type === undefined) return 'any';
	return [schema.type]
		.flat()
		.map((type) => {
			if (type === 'array' && schema.items !== undefined) return `array of ${typeOf(schema.items)}`;
			if (type === 'object' && isObject(schema.additionalProperties) && !isObject(schema.properties))
				return `map of ${typeOf(schema.additionalProperties)}`;
			if (type === 'string' && typeof schema.format === 'string') return `string (${escape(schema.format)})`;
			return escape(type);
		})
		.join(' | ');
};

/**
 * The rules of a value in words (lengths, bounds, pattern, default).
 * @param {Node} schema
 * @returns {string[]}
 */
const rulesOf = (schema) => {
	/** @param {unknown} min @param {unknown} max @param {string} unit */
	const range = (min, max, unit) =>
		min !== undefined && max !== undefined
			? [`${min}–${max}${unit}`]
			: min !== undefined
				? [`at least ${min}${unit}`]
				: max !== undefined
					? [`at most ${max}${unit}`]
					: [];
	return [
		...range(schema.minLength, schema.maxLength, ' characters'),
		...range(schema.minimum, schema.maximum, ''),
		...range(schema.minItems, schema.maxItems, ' items'),
		...(schema.maxProperties === undefined ? [] : [`at most ${schema.maxProperties} members`]),
		...(typeof schema.pattern === 'string' ? [`pattern ${schema.pattern}`] : []),
		...(schema.default === undefined ? [] : [`default ${JSON.stringify(schema.default)}`]),
	];
};

/**
 * The notes of a field or parameter as HTML: its description, then its rules (`Minor units. 1–100.`).
 * @param {unknown} description
 * @param {unknown} schema
 */
const notesOf = (description, schema) => {
	const parts = [...(typeof description === 'string' ? [description] : []), ...rulesOf(isObject(schema) ? schema : {})]
		.map((part) => part.trim().replace(/\.$/, ''))
		.filter(Boolean)
		.map((part) => part.charAt(0).toUpperCase() + part.slice(1));
	return parts.length > 0 ? `${escape(parts.join('. '))}.` : '';
};

/**
 * The object schema a node describes inline (to list its fields), or null.
 * @param {unknown} schema
 * @returns {Node | null}
 */
const inlineObject = (schema) => (isObject(schema) && isObject(schema.properties) ? schema : null);

/**
 * The fields of an object schema as table rows: nested objects as `a.b`, items of lists as `a[].b`.
 * @param {Node} schema
 * @param {string} [prefix]
 * @param {number} [depth]
 * @returns {string[]}
 */
const fieldRows = (schema, prefix = '', depth = 0) => {
	const required = new Set(Array.isArray(schema.required) ? schema.required : []);
	return Object.entries(/** @type {Node} */ (schema.properties)).flatMap(([name, child]) => {
		const field = `${prefix}${name}`;
		const node = isObject(child) ? child : {};
		const row = `<tr><td><code>${escape(field)}</code></td><td>${typeOf(node)}</td><td>${required.has(name) ? 'yes' : 'no'}</td><td>${notesOf(node.description, node)}</td></tr>`;
		if (depth >= 4) return [row];
		// an object written inline (also as a branch of oneOf/anyOf, for example `object or null`) lists its fields
		const branches = [node, ...[node.oneOf ?? node.anyOf ?? []].flat()];
		const nested = branches.map(inlineObject).filter((object) => object !== null);
		const items = inlineObject(node.items);
		return [
			row,
			...nested.flatMap((object) => fieldRows(object, `${field}.`, depth + 1)),
			...(items ? fieldRows(items, `${field}[].`, depth + 1) : []),
		];
	});
};

/**
 * A schema as HTML: a field table for an object, else one line with its type.
 * @param {unknown} schema
 */
const schemaHtml = (schema) => {
	const object = inlineObject(schema);
	const description = isObject(schema) && typeof schema.description === 'string' ? `<p>${escape(schema.description)}</p>` : '';
	if (object && Object.keys(object.properties).length > 0)
		return `${description}<table><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody>${fieldRows(object).join('')}</tbody></table>`;
	return `${description}<p>${typeOf(schema)}</p>`;
};

/** What each auth mode means for the caller. */
const AUTH_TEXT = Object.freeze({
	browser: 'browser token from the website (or the server token with SS-Visitor-IP)',
	server: 'server token (your server only)',
	ticket: 'ticket (admin widgets)',
});

/**
 * One operation.
 * @param {string} method
 * @param {string} path
 * @param {Node} operation
 * @param {Node} openapi
 */
const operationHtml = (method, path, operation, openapi) => {
	const auth = /** @type {keyof typeof AUTH_TEXT} */ (operation['x-ss-auth']);
	const features = [operation['x-ss-feature'] ?? []].flat();
	const parameters = Array.isArray(operation.parameters) ? operation.parameters : [];
	const own = parameters.filter((parameter) => isObject(parameter) && typeof parameter.name === 'string');
	const sharedParameters = parameters
		.map((parameter) => (isObject(parameter) && typeof parameter.$ref === 'string' ? parameter.$ref.split('/').pop() : null))
		.map((name) => openapi.components?.parameters?.[name ?? ''])
		.filter((parameter) => isObject(parameter) && typeof parameter.name === 'string');
	const shared = sharedParameters.filter((parameter) => parameter.required !== true).map((parameter) => parameter.name);
	const sharedRequired = sharedParameters.filter((parameter) => parameter.required === true).map((parameter) => parameter.name);
	const body = operation.requestBody?.content?.['application/json']?.schema;
	const [status, answer] =
		Object.entries(/** @type {Node} */ (operation.responses ?? {})).find(([code]) => /^2/.test(code)) ?? [];
	const answerSchema = answer?.content?.['application/json']?.schema;
	return [
		`<section class="ss-api-op" id="${escape(apiAnchor(method, path))}">`,
		`<h3><code>${escape(`${method} ${path}`)}</code>${operation.summary ? ` ${escape(operation.summary)}` : ''}</h3>`,
		operation.description ? `<p>${escape(operation.description)}</p>` : '',
		`<p><strong>Auth:</strong> ${escape(
			auth === 'server' && operation['x-ss-access'] === 'staff'
				? 'server token and the verified sign-in of a signed-in staff member (the server token alone changes nothing)'
				: (AUTH_TEXT[auth] ?? auth ?? 'none'),
		)}${
			operation['x-ss-permission'] ? ` with the permission <code>${escape(operation['x-ss-permission'])}</code>` : ''
		}. <strong>Feature:</strong> ${features.length > 0 ? features.map((key) => `<code>${escape(key)}</code>`).join(' or ') : 'always on'}.</p>`,
		own.length > 0
			? `<table><thead><tr><th>Parameter</th><th>In</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody>${own
					.map(
						(parameter) =>
							`<tr><td><code>${escape(parameter.name)}</code></td><td>${escape(parameter.in)}</td><td>${typeOf(parameter.schema)}</td><td>${parameter.required ? 'yes' : 'no'}</td><td>${notesOf(parameter.description, parameter.schema)}</td></tr>`,
					)
					.join('')}</tbody></table>`
			: '',
		sharedRequired.length > 0
			? `<p>Required headers: ${sharedRequired.map((name) => `<code>${escape(name)}</code>`).join(', ')}.</p>`
			: '',
		shared.length > 0 ? `<p>Optional headers: ${shared.map((name) => `<code>${escape(name)}</code>`).join(', ')}.</p>` : '',
		body === undefined ? '' : `<h4>Request body (JSON)</h4>${schemaHtml(body)}`,
		status === undefined
			? ''
			: `<h4>Answer ${escape(status)}${answerSchema === undefined ? '' : ' (JSON)'}</h4>${
					answerSchema === undefined ? `<p>${escape(answer?.description ?? '')}</p>` : schemaHtml(answerSchema)
				}`,
		'</section>',
	].join('');
};

/**
 * The API reference as HTML: every operation, then the shared objects. Errors are RFC 9457 problems
 * (`application/problem+json`) whose `type` ends with a stable code.
 * @param {unknown} openapi the product's `openapi.json`
 * @returns {string}
 */
export const renderApiReference = (openapi) => {
	const doc = /** @type {Node} */ (isObject(openapi) ? openapi : {});
	const operations = Object.entries(isObject(doc.paths) ? doc.paths : {}).flatMap(([path, methods]) =>
		Object.entries(isObject(methods) ? methods : {})
			.filter(([, operation]) => isObject(operation))
			.map(([method, operation]) => /** @type {const} */ ([method.toUpperCase(), path, /** @type {Node} */ (operation)])),
	);
	const schemas = isObject(doc.components?.schemas) ? doc.components.schemas : {};
	return [
		'<div class="ss-api">',
		...operations.map(([method, path, operation]) => operationHtml(method, path, operation, doc)),
		Object.keys(schemas).length > 0 ? '<h3>Objects</h3>' : '',
		...Object.entries(schemas).map(
			([name, schema]) =>
				`<section class="ss-api-schema" id="${escape(schemaAnchor(name))}"><h4>${escape(name)}</h4>${schemaHtml(schema)}</section>`,
		),
		'</div>',
	].join('\n');
};
